// Generated by tilelang.hexagon.emitter: elementwise HVX vector pipe-v1.
// Pragmatic Hexagon lowering for the VTCM-staged silu_mul pattern:
// two VTCM input slots are used as a ping-pong buffer.  One worker copies
// panel p+1 while the other five workers compute panel p.
// This overlaps the DDR->VTCM staging of panel p+1 with the HVX silu/mul work
// of panel p with one attnops_pool_run for the whole kernel.
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include "attnops.h"
#include "HAP_perf.h"
#include "hexagon_rt.h"

typedef hrt_f16 f16;

#define PANEL 1024
#define NWORKERS 6
#define PIPE_CHUNKS 16
#define PIPE_SLOT_BYTES ((size_t)(2 * PANEL * sizeof(f16)))
#define PIPE_G(slot) (V + (size_t)(slot) * PIPE_SLOT_BYTES)
#define PIPE_U(slot) (V + (size_t)(slot) * PIPE_SLOT_BYTES + PANEL * sizeof(f16))
#define VELEM_VTCM_BYTES ((size_t)(2 * PIPE_SLOT_BYTES))

static const f16 *g_pipe_G;
static const f16 *g_pipe_U;
static f16 *g_pipe_O;
static size_t g_pipe_total;
static size_t g_pipe_cur_base;
static int g_pipe_cur_slot;
static int g_pipe_panels;
static int g_pipe_abl;
#define PIPE_MAX_PANELS 16384
static volatile int g_pipe_ready[PIPE_MAX_PANELS];
static volatile int g_pipe_done[PIPE_MAX_PANELS];

static inline void attnops_tl_silu_pipe_copy_chunk(uint8_t *dst, const f16 *src, size_t base, int chunk) {
    size_t idx = base + (size_t)chunk * 64;
    if (idx >= g_pipe_total) return;
    size_t elems = 64;
    if (idx + elems > g_pipe_total) elems = g_pipe_total - idx;
    size_t bytes = elems * sizeof(f16);
    if (bytes) hrt_copy_128_dcfetch(dst + (size_t)chunk * 128, (const uint8_t *)(src + idx), bytes);
}

static void attnops_tl_silu_pipe_copy_panel_worker(int wid) {
    uint8_t *V = HRT_VTCM_BASE();
    for (int c = wid; c < PIPE_CHUNKS; c += NWORKERS) {
        attnops_tl_silu_pipe_copy_chunk(PIPE_G(g_pipe_cur_slot), g_pipe_G, g_pipe_cur_base, c);
        attnops_tl_silu_pipe_copy_chunk(PIPE_U(g_pipe_cur_slot), g_pipe_U, g_pipe_cur_base, c);
    }
}

static void attnops_tl_silu_pipe_pipeline_worker(int wid) {
    uint8_t *V = HRT_VTCM_BASE();
    if (wid == NWORKERS - 1) {
        for (int p = 0; p < g_pipe_panels; p++) {
            if (p >= 2) while (g_pipe_done[p - 2] < NWORKERS - 1) { }
            int slot = p & 1;
            size_t base = (size_t)p * PANEL;
            if (!(g_pipe_abl & 1)) {
                for (int c = 0; c < PIPE_CHUNKS; c++) {
                    attnops_tl_silu_pipe_copy_chunk(PIPE_G(slot), g_pipe_G, base, c);
                    attnops_tl_silu_pipe_copy_chunk(PIPE_U(slot), g_pipe_U, base, c);
                }
            }
            g_pipe_ready[p] = 1;
        }
        return;
    }
    for (int p = 0; p < g_pipe_panels; p++) {
        while (!g_pipe_ready[p]) { }
        int cur = p & 1;
        size_t base = (size_t)p * PANEL;
        if (!(g_pipe_abl & 2)) {
            for (int c = wid; c < PIPE_CHUNKS; c += NWORKERS - 1) {
                size_t idx = base + (size_t)c * 64;
                if (idx + 64 > g_pipe_total) continue;
                HVX_Vector hv0 = *(const HVX_Vector *)(PIPE_G(cur) + (size_t)c * 128);
                HVX_Vector hv1 = *(const HVX_Vector *)(PIPE_U(cur) + (size_t)c * 128);
                HVX_Vector hv2 = Q6_Vhf_vmpy_VhfVhf(hv0, hv1);
                HVX_Vector hv3 = hrt_splat_h(0x3C00);
                HVX_Vector hv5 = hrt_splat_h(0xBC00);
                HVX_Vector hv6 = Q6_Vhf_vmpy_VhfVhf(hv0, hv5);
                HVX_Vector hv7 = hrt_exp_fp16(hv6);
                HVX_Vector hv8 = Q6_Vhf_vadd_VhfVhf(hv3, hv7);
                HVX_Vector hv9 = hrt_vhf_div_approx(hv2, hv8);
                *(HVX_Vector *)(g_pipe_O + idx) = hv9;
            }
        }
        __sync_fetch_and_add((int *)&g_pipe_done[p], 1);
    }
}

int attnops_tl_silu_pipe(remote_handle64 h, unsigned char *slab, int slabLen,
                int M, int FF, int abl) {
    (void)h;
    if (M <= 0 || FF <= 0 || FF % 64) return -2;
    size_t elems = (size_t)M * FF;
    size_t g_sz = elems * 2;
    size_t u_off = HRT_ALIGN128(g_sz);
    size_t u_sz = elems * 2;
    size_t o_off = HRT_ALIGN128(u_off + u_sz);
    size_t o_sz = elems * 2;
    size_t prof_off = HRT_ALIGN128(o_off + o_sz);
    if ((size_t)slabLen < prof_off + 16) return -1;
    if (!HRT_VTCM_READY() || VELEM_VTCM_BYTES > HRT_VTCM_SIZE()) return -4;
    g_pipe_G = (const f16 *)slab;
    g_pipe_U = (const f16 *)(slab + u_off);
    g_pipe_O = (f16 *)(slab + o_off);
    g_pipe_total = elems;
    uint8_t *V = HRT_VTCM_BASE();
    (void)V;
    HRT_PROF_DECL(prof, slab, prof_off);
    HRT_PROF_CLEAR(prof, 16);
    int panels = (int)((elems + PANEL - 1) / PANEL);
    if (panels > PIPE_MAX_PANELS) return -2;
    if (panels <= 0) return 0;
    uint64_t tt = HAP_perf_get_qtimer_count();
    for (int p = 0; p < panels; p++) { g_pipe_ready[p] = 0; g_pipe_done[p] = 0; }
    g_pipe_panels = panels;
    g_pipe_abl = abl;
    attnops_pool_run(attnops_tl_silu_pipe_pipeline_worker, NWORKERS);
    prof[0] = (int32_t)(HAP_perf_get_qtimer_count() - tt);
    prof[3] = panels;
    return 0;
}
